  "hp.m.item": "सामान ते सर्विस, रेट, HSN ते GST समेत। CSV फाइल कन्नै इक्कै बारी मते इम्पोर्ट करो।",
  "hp.m.doc": "सारे टूलें दे सेव कीते दे डॉक्यूमेंट। Excel आस्तै लिस्ट डाउनलोड करो।",
