  "pr.f_daily": "इन्नी रोज दी वेज तगर मलाजम दा हिस्सा नेईं (₹)",
  "pr.pfintro": "म्हीने दियां तनखाह स्लिपां कन्नै EPFO यूनिफाइड पोर्टल आस्तै ECR टेक्स्ट फ़ाइल ते चलान दियां रकमां बनदियां न। पैह्लें स्लिपां बनाओ (तनखाह टैब); जिनें मलाजमें दी स्लिप नेईं ऐ ओह् थल्लै लिखे दे न।",
  "pr.unver_pf": "अपलोड करने शा पैह्लें चैक करो: एह् बनाने बेलै (14 Nov 2026) EPFO दा अपना फ़ाइल-स्ट्रक्चर डॉक्यूमेंट नेईं खुल्ली सकेआ। 11 फील्ड ते उंदा क्रम पेरोल सॉफ्टवेयर बनाने आह्‌लें दी दस्सी दी जानकारी मताबक ऐ। फ़ाइल EPFO पोर्टल दे ECR पेज पर अपलोड करो; जेकर पोर्टल कोई लाइन रिजेक्ट करदा ऐ तां ओह् कारण दसदा ऐ।",
