  "pr.esiintro": "म्हीने दियां तनखाह स्लिपां कन्नै ESIC एम्प्लॉयर पोर्टल आस्तै म्हीने दी कंट्रीब्यूशन शीट ते चलान दियां रकमां बनदियां न। फ़ाइल च सिर्फ ओह् मलाजम न जिंदी पे वेज हद्द दे अंदर ऐ (जां जेह्ड़े उस्सै छे-माही च पैह्लें कवर हे)।",
  "pr.unver_esi": "एह् शीट ESIC पोर्टल दे अपने Monthly Contribution टेम्पलेट मताबक ऐ (15 नवंबर 2026 गी चैक कीती): छे कॉलम टेक्स्ट च, Excel 97-2003 (.xls) फ़ाइल। जिनें मलाजमें गी इस म्हीने वेज नेईं मिली, ओह् बी रीज़न कोड कन्नै लिस्ट च औंदे न। पैह्लें इक म्हीना अपलोड करियै पोर्टल दा नतीजा दिक्खी लैओ।",
