  "it.m_senior": "60 जां मती उमर दे रेज़िडेंट जिंदी कोई बिजनेस जां प्रोफेशनल इनकम नेईं, एडवांस टैक्स नेईं भरदे (सेक्शन 403(3))। बाकी रकम रिटर्न भरदे बेलै देओ।",
  "it.m_below": "TDS दे बाद टैक्स {n} ऐ, ₹10,000 शा घट्ट, इस करी कोई एडवांस टैक्स नेईं बनदा (सेक्शन 404)। बाकी रकम रिटर्न भरदे बेलै देओ।",
