  "it.m_past": "एह् साल खत्म होई चुके दा ऐ। 31 March दे बाद भरेआ एडवांस टैक्स इस साल दे एडवांस टैक्स च नेईं गिनेआ जंदा; थल्लै आह्‌ला ब्याज दसदा ऐ जे कमी किन्नी म्हैंगी पौंदी ऐ।",
