  "it.basis": "एह् आंकड़े कुस अधार पर न ({d} मताबक)",
  "it.b1": "रेट ({d} मताबक), टैक्स साल 2026-27: नमां रिजीम ₹4 लक्ख तगर जीरो, ₹8 लक्ख तगर 5%, ₹12 लक्ख तगर 10%, ₹16 लक्ख तगर 15%, ₹20 लक्ख तगर 20%, ₹24 लक्ख तगर 25%, उस शा उप्पर 30%; रिबेट ऐसी जे ₹12 लक्ख तगर दी इनकम पर कोई टैक्स नेईं, थोह्ड़ा उप्पर मार्जिनल रिलीफ; तनखाह उप्पर स्टैंडर्ड डिडक्शन ₹75,000। पुराना रिजीम: ₹2.5 लक्ख तगर जीरो (60 पर ₹3 लक्ख, 80 पर ₹5 लक्ख), ₹5 लक्ख तगर 5%, ₹10 लक्ख तगर 20%, उस शा उप्पर 30%; ₹5 लक्ख तगर रिबेट ₹12,500; स्टैंडर्ड डिडक्शन ₹50,000। एह् उऐ रेट न जेह्ड़े तनखाह स्लिप टूल पैह्लें गै बरतदा ऐ; इस बिल्ड च Finance Act थमां दबारा नेईं पढ़े गे, इस करी चैक करी लैओ।",
  "it.b2": "एडवांस टैक्स (Income-tax Act 2025, सेक्शन 403 थमां 408): जिसलै TDS दे बाद टैक्स ₹10,000 जां मता होऐ; 15 June तगर 15%, 15 September तगर 45%, 15 December तगर 75%, 15 March तगर पूरा; प्रिज़म्प्टिव टैक्सपेयर सब 15 March तगर भरदा ऐ; 31 March तगर दा पेमेंट उस्सै साल च गिनेआ जंदा ऐ; 60 जां मती उमर दे रेज़िडेंट जिंदी बिजनेस इनकम नेईं, छूट च न।",
  "it.b3": "ब्याज: सेक्शन 424 (पुराना 234B) कमी उप्पर हर म्हीने जां म्हीने दे हिस्से दा 1% ऐ, जिसलै टैक्स दा 90% शा घट्ट भरेआ होऐ; सेक्शन 425 (पुराना 234C) पैह्लियें त्रै किस्तें चा हर इक दी कमी उप्पर 3% ऐ (जेकर 15 June तगर 12% ते 15 September तगर 36% भरेआ होऐ तां नेईं) ते March दी कमी उप्पर 1%।",
  "it.b4": "उप्पर दे सेक्शन 15 नवंबर 2026 गी इनकम टैक्स डिपार्टमेंट दी वेबसाइट (incometaxindia.gov.in) पर दित्ते दे सरकारी टेक्स्ट कन्नै शब्द-ब-शब्द चैक कीते गे। छपेआ दा एक्ट गै मन्नेआ जंदा ऐ।",
  "it.b5": "खातें दा मुनाफा टैक्सेबल मुनाफा नेईं होंदा: Act तैह्त डेप्रिसिएशन, नामंजूर खर्चे ते प्रिज़म्प्टिव नियम इसगी बदली दिंदे न। एह् प्लान ते डेटा शीट अपने अकाउंटेंट गी देओ।",
  "it.b6": "एह् नेईं कड्ढे जंदे: सरचार्ज, खास रेट आह्‌ले कैपिटल गेन, बदेशी टैक्स राहत, नाबालग दी इनकम उप्पर टैक्स, ते लेट रिटर्न भरने दा ब्याज।",
  "it.b7": "किश बी फाइल नेईं होंदा ते तुंदे खातें च किश पोस्ट नेईं होंदा।",
  "it.itr_h": "किश सवालें दे जवाब देओ ते दिक्खो केह्ड़ा रिटर्न फॉर्म ठीक ऐ, कीऽ, ते केह्ड़े कागज त्यार रक्खने न।",
