  "it.q_crypto": "मैं क्रिप्टो जनेह् वर्चुअल डिजिटल एसेट बेचे",
  "it.formd_ITR-1": "तनखाह जां पेंशन, दो तगर मकान ते ब्याज जनेह् होर सरोतें आह्‌ले रेज़िडेंट बंदे आस्तै, जिसदी कुल इनकम ₹50 लक्ख तगर होऐ।",
  "it.formd_ITR-2": "ऐसे बंदे जां HUF आस्तै जिंदी बिजनेस जां प्रोफेशन इनकम नेईं, पर कैपिटल गेन न, ₹50 लक्ख शा उप्पर इनकम ऐ, दो शा मते मकान न, बदेशी जायदाद जां इनकम ऐ, जां जेह्ड़े ITR-1 च नेईं औंदे।",
  "it.formd_ITR-3": "ऐसे बंदे जां HUF आस्तै जिंदी बिजनेस जां प्रोफेशन इनकम प्रिज़म्प्टिव स्कीम च नेईं ऐ, कुसै फर्म च पार्टनर, जां जेह्ड़े ITR-4 च नेईं औंदे।",
  "it.formd_ITR-4": "प्रिज़म्प्टिव बिजनेस इनकम आह्‌ले रेज़िडेंट बंदे जां HUF आस्तै, कुल इनकम ₹50 लक्ख तगर, तनखाह जां पेंशन, दो तगर मकान ते होर सरोत।",
  "it.formd_ITR-5": "फर्म, LLP, एसोसिएशन ऑफ पर्सन्स ते बॉडी ऑफ इंडिविजुअल्स आस्तै।",
  "it.formd_ITR-6": "कंपनियें आस्तै, उनेंगी छोड़ियै जेह्ड़ियां धर्मार्थ जां धार्मिक कम्में दी छूट मंगदियां न।",
  "it.formd_ITR-7": "ट्रस्ट, संस्थाएं, राजनीतिक पार्टियें ते ऐसे लोकें आस्तै।",
  "it.w_company": "कंपनी ITR-6 भरदी ऐ।",
  "it.w_firm": "फर्म, LLP जां एसोसिएशन ITR-5 भरदे न।",
  "it.w_other": "ट्रस्ट, संस्थां ते राजनीतिक पार्टियां ITR-7 भरदियां न।",
  "it.w_partner": "जिस फर्म च तुस पार्टनर ओ उस कोला मिली दी तनखाह जां ब्याज बिजनेस इनकम ऐ, जेह्ड़ी ITR-3 च दस्सी जंदी ऐ।",
  "it.w_business": "तुस बिजनेस जां प्रोफेशनल मुनाफा खातें थमां कड्ढदे ओ, इस आस्तै ITR-3 चाहिदा।",
  "it.w_presnot": "प्रिज़म्प्टिव फॉर्म बंदें ते HUF आस्तै ऐ।",
  "it.w_nonres": "जेह्ड़ा रेज़िडेंट नेईं ऐ ओह् ITR-1 जां ITR-4 नेईं बरती सकदा।",
  "it.w_over50": "₹50 लक्ख शा उप्पर दी कुल इनकम पर ITR-1 ते ITR-4 नेईं चलदे।",
  "it.w_capgain": "लिस्टेड शेयर दी निक्की हद्द दे अलावा कैपिटल गेन होन तां ITR-2 जां ITR-3 चाहिदा।",
  "it.w_houses": "दो शा मते मकान होन तां ITR-1 ते ITR-4 नेईं चलदे।",
  "it.w_foreign": "बदेशी जायदाद जां बदेशी इनकम होऐ तां ITR-2 जां ITR-3 चाहिदा।",
  "it.w_director": "कंपनी दा डायरेक्टर ITR-1 जां ITR-4 नेईं बरती सकदा।",
  "it.w_unlisted": "अनलिस्टेड शेयर होन तां ITR-1 ते ITR-4 नेईं चलदे।",
  "it.w_agri": "₹5,000 शा उप्पर खेती दी इनकम पर ITR-1 ते ITR-4 नेईं चलदे।",
  "it.w_loss": "अग्गें लेई जाने जां सेट-ऑफ करने आह्‌ले घाटे होन तां ITR-2 जां ITR-3 चाहिदा।",
  "it.w_esop": "एम्प्लॉयर दे शेयरें उप्पर टाले दा टैक्स होऐ तां ITR-2 जां ITR-3 चाहिदा।",
  "it.w_crypto": "वर्चुअल डिजिटल एसेट थमां इनकम होऐ तां ITR-2 जां ITR-3 चाहिदा।",
  "it.w_huf": "ITR-1 सिर्फ बंदें आस्तै ऐ; बिना बिजनेस इनकम आह्‌ला HUF ITR-2 भरदा ऐ।",
  "it.w_pres2": "तुंदे होर जवाबें करी ITR-4 नेईं चलदा, इस करी बिजनेस इनकम ITR-3 च जंदी ऐ।",
  "it.w_pres": "प्रिज़म्प्टिव बिजनेस इनकम ते सादी होर इनकम आस्तै ITR-4 ठीक ऐ।",
  "it.w_simple": "सिर्फ तनखाह, मकान ते ब्याज, हद्दें दे अंदर, तां ITR-1 ठीक ऐ।",
  "it.n_forms": "शर्तां 31 March 2026 गी खत्म होए दे साल आस्तै जारी रिटर्नें मताबक न (टैक्स पोर्टलें मताबक ITR-1 ते ITR-4 च हुन दो तगर मकान चलदे न)। टैक्स साल 2026-27 दे रिटर्न Income-tax Rules, 2026 तैह्त हुन्नै जारी होने न: भरने शा पैह्लें फॉर्म च लिखी दी लिस्ट पढ़ो जे कुन उसगी नेईं बरती सकदा।",
  "it.n_ltcg": "किश सालें च लिस्टेड शेयर जां इक्विटी फंड उप्पर निक्के लॉन्ग-टर्म गेन ITR-1 ते ITR-4 च चलदे हे; 2026-27 आस्तै एह् पक्का नेईं, इस करी ITR-2 सुरक्षत ऐ ते फॉर्म दी अपनी लिस्ट गै खीरी ऐ।",
  "it.n_ae": "सेक्शन 44AE (माल ढोने आह्‌ली गड्डी) दियां अपनियां शर्तां न; प्रिज़म्प्टिव फॉर्म बरतने शा पैह्लें उनेंगी चैक करी लैओ।",
  "it.n_tax": "प्रिज़म्प्टिव रेट शा घट्ट मुनाफा दस्सने आस्तै खाते चाहिदे न ते ऑडिट बी लग्गी सकदा ऐ: तां रिटर्न ITR-3 होंदा ऐ।",
