  "ca.t": "मेरे अकाउंटेंट आस्तै फ़ाइल",
  "ca.intro": "इक बिजनेस ते अवधि गी इक्कै सिर्फ-पढ़ने आह्‌ली फ़ाइल (.nsca) च पैक करदा ऐ। इसगी WhatsApp जां ईमेल कन्नै अपने अकाउंटेंट गी भेजो। ओह् इसगी ca.niveshsahayak.in पर खोह्लदे न, खाते पढ़दे न, सवाल जोड़दे न ते कमेंट तुसेंगी वापस भेजदे न।",
  "ca.notlive": "एह् फ़ाइल सौंपना ऐ, कोई लाइव शेयर्ड लॉगिन नेईं। तुंदा अकाउंटेंट खाते उ’आं गै दिक्खदा ऐ जि’यां फ़ाइल बनाने बेलै हे। लाइव लॉगिन आस्तै ऐसा सर्वर चाहिदा जेह्ड़ा तुंदे खाते रक्खै, ते Nivesh Sahayak कोल कोई सर्वर नेईं: तुंदे खाते तुंदे डिवाइस पर रौंह्दे न। नमियें एंट्रियें आस्तै नमीं फ़ाइल बनाओ।",
  "ca.what": "इस च केह् जंदा ऐ",
  "ca.earlier": "पैह्ली तरीक शा पैह्लें दियां एंट्रियां बी (शुरू दे बैलेंस ते एजिंग आस्तै जरूरी)",
  "ca.items": "खरीद ते बिक्री रेट आह्‌ली आइटम लिस्ट (स्टॉक आस्तै जरूरी)",
  "ca.extra": "सिर्फ टिक करने पर",
  "ca.extrah": "टिक नेईं करो तां छोड़ी दित्ता जंदा ऐ। तस्वीरां (लोगो, साइन), तुंदा PIN ते बैकअप सेटिंग कदें बी शामल नेईं होंदे।",
  "ca.orders": "कोटेशन, प्रोफॉर्मा इनवॉइस, सेल्स ऑर्डर, चलान ते परचेज ऑर्डर",
  "ca.staff": "तनखाह स्लिपां, स्टाफ एडवांस, लोन ते EMI, पेटी कैश, ते मलाजमें दी लिस्ट",
