  "ca.codeh": "एह् कोड अपने मैसेज च भेजो, जां कॉल पर पढ़ियै दस्सो। तुंदा अकाउंटेंट इसगी फ़ाइल च दिक्खने आह्‌ले कोड कन्नै मलांदा ऐ, जिस कन्नै रस्ते च बदली दी फ़ाइल फड़ोई जंदी ऐ।",
