  "ca.how": "फ़ाइल WhatsApp जां ईमेल कन्नै अटैचमेंट दे तौर पर भेजो। जेकर WhatsApp नां दे खीर च .nsca दस्सै तां नां नेईं बदलो।",
  "ca.cT": "CA दे कमेंट",
  "ca.cIntro": "तुंदा अकाउंटेंट सवालें ते कमेंटें दी इक निक्की फ़ाइल (.nsca-comments) वापस भेजदा ऐ। हर सवाल उसदी एंट्री कन्नै दिक्खने आस्तै इसगी इत्थें लोड करो। जवाब देओ, बंद मार्क करो, ते वापस भेजने आस्तै फ़ाइल फ्ही सेव करो।",
