  "ca.party": "पार्टी",
  "ca.screen": "स्क्रीन",
  "ca.general": "आम कमेंट",
  "cv.h1": "अकाउंटेंट व्यूअर: क्लाइंट दी भेजी दी खातें दी फ़ाइल खोह्लो",
  "cv.intro": "तुंदा क्लाइंट कुसै अवधि दे अपने खाते इक फ़ाइल च पैक करियै WhatsApp जां ईमेल कन्नै तुसेंगी भेजदा ऐ। इसगी इत्थें खोह्लो ते पढ़ो: बकाया, पार्टियां, लेजर, डे बुक, GST दा हिसाब, फाइनल अकाउंट ते हर डॉक्यूमेंट। लब्भो ते फिल्टर करो, कुसै बी एंट्री पर सवाल पुच्छो, ते अपने कमेंट इक निक्की फ़ाइल च वापस भेजो। मुफ्त, बिना लॉगिन, ते किश अपलोड नेईं होंदा: फ़ाइल तुंदे ब्राउज़र दे अंदर गै पढ़ी जंदी ऐ।",
  "cv.drop": ".nsca फ़ाइल इत्थें छोड़ो",
  "cv.choose": "फ़ाइल चुनो",
  "cv.dropnote": "फ़ाइल इस्सै डिवाइस पर रौंह्दी ऐ। इत्थें किश सेव नेईं होंदा ते तुस इत्थुआं क्लाइंट दे खाते नेईं बदली सकदे।",
  "cv.nav.home": "सारांश",
  "cv.docs": "डॉक्यूमेंट",
  "cv.day": "डे बुक",
  "cv.fin": "फाइनल अकाउंट",
  "cv.gst": "GST दा हिसाब",
  "cv.cT": "सवाल ते कमेंट",
  "cv.how.h": "एह् कि’यां कम्म करदा ऐ",
  "cv.how.1": "तुंदा क्लाइंट Nivesh Sahayak खोह्लदा ऐ, मेरा डेटा च अपने अकाउंटेंट गी भेजो पर जंदा ऐ, ते इक बिजनेस ते अवधि आस्तै \"मेरे अकाउंटेंट आस्तै फ़ाइल बनाओ\" चुनदा ऐ।",
  "cv.how.2": "ओह् तुसेंगी फ़ाइल (.nsca पर खत्म) ते उस्सै मैसेज च इक निक्का चैक कोड भेजदे न।",
  "cv.how.3": "तुस इस पेज पर फ़ाइल खोह्लदे ओ। पेज दसदा ऐ जे फ़ाइल बदली नेईं ऐ, ते क्लाइंट दा दित्ता चैक कोड लिखियै मलाने दिंदा ऐ।",
  "cv.how.4": "खाते पढ़ो, लब्भो, ते कुसै बी डॉक्यूमेंट, डे बुक एंट्री जां स्क्रीन पर \"सवाल जां कमेंट जोड़ो\" दबाओ। जेह्ड़ा किश तुस लिखदे ओ ओह् इस्सै ब्राउज़र च रौंह्दा ऐ।",
  "cv.how.5": "कम्म पूरा होने पर \"सवाल ते कमेंट\" खोह्लो ते निक्की .nsca-comments फ़ाइल वापस भेजो। तुंदा क्लाइंट उसगी लोड करदा ऐ ते हर सवाल उसदी एंट्री कन्नै दिक्खदा ऐ। ओह् जवाब देई सकदे न, ते तुस जवाब इत्थें लोड करी सकदे ओ।",
  "cv.live.h": "फ़ाइल सौंपना, लाइव लॉगिन नेईं",
  "cv.live.p": "एह् फ़ाइल सौंपना ऐ। तुस क्लाइंट दे अकाउंट च लॉगिन नेईं करदे ते उंदे बाद दे बदलाऽ नेईं दिक्खदे। लाइव शेयर्ड लॉगिन आस्तै ऐसा सर्वर चाहिदा जेह्ड़ा खाते रक्खै, ते Nivesh Sahayak कोल कोई सर्वर नेईं: खाते क्लाइंट दे डिवाइस पर रौंह्दे न। नमीं अवधि जां सुधार दे बाद क्लाइंट कोला नमीं फ़ाइल मंगो।",
  "cv.safe.h": "फ़ाइल च केह् ऐ, ते केह् नेईं",
  "cv.safe.p": "केह् जाग एह् तुंदा क्लाइंट टिक करदा ऐ। आमतौर पर फ़ाइल च इक बिजनेस दियां अवधि दे खीर तगर दियां एंट्रियां, पार्टियां ते आइटम होंदे न। कोटेशन ते ऑर्डर, तनखाह ते स्टाफ दे रिकॉर्ड, फोन नंबर ते ईमेल पते, ते बिजनेस दे बैंक खाते दी जानकारी तां गै जंदी ऐ जेकर क्लाइंट टिक करै। तस्वीरां, PIN ते बैकअप सेटिंग कदें बी शामल नेईं होंदे। फ़ाइल च चेकसम होंदा ऐ, इस करी कोई बी बदलाऽ इस पेज पर दिक्खदा ऐ। चेकसम उस बंदे गी नेईं रोकी सकदा जेह्ड़ा फ़ाइल बदलियै उसगी दबारा कड्ढी लै, इस करी चैक कोड गी क्लाइंट दे बक्खरे भेजे दे कोड कन्नै मलाओ।",
  "cv.readonly": "एह् इक फ़ाइल दा सिर्फ-पढ़ने आह्‌ला व्यू ऐ: इत्थें किश बदलेआ जां सेव नेईं कीता जाई सकदा।",
  "cv.notfile": "एह् Nivesh Sahayak दी अकाउंटेंट फ़ाइल (.nsca) नेईं ऐ।",
  "cv.iscomments": "एह् कमेंट फ़ाइल ऐ। पैह्लें खातें दी फ़ाइल (.nsca) खोह्लो, फ्ही \"सवाल ते कमेंट\" थमां कमेंट लोड करो।",
  "cv.newer": "एह् फ़ाइल नमें वर्ज़न कन्नै बनी दी ऐ। पेज रीलोड करो ते फ्ही कोशश करो।",
  "cv.nostore": "तुंदे कमेंट इस ब्राउज़र च नेईं रक्खे जाई सके। हुनै कमेंट फ़ाइल सेव करो।",
