  "hm.h.note": "एह् तुंदे लिखे दे बिलें ते खर्चें थमां बने दा मोटा अंदाजा ऐ, अकाउंटिंग जां फाइनेंशियल सलाह नेईं। हत्थै दा स्टॉक ते नेईं लिखे दे बिल नेईं गिने जंदे; मार्जिन उनें गै म्हीनें दी बिक्री चा खरीद ते खर्चे घटाइयै ऐ।",
