  "hm.h.cash.low": "खर्चे मताबक कैश बड़ा घट्ट ऐ। पैह्लें बकाया उगाहो ते जेह्ड़ा रुकी सकदा ऐ उसगी टाली देओ।",
  "hm.h.cash.rule": "कैश ते बैंक बैलेंस गी पिछले 3 पूरे म्हीनें दी औसत म्हीनेवार खरीद ते खर्चें कन्नै भाग दित्ता जंदा ऐ। 2 म्हीने जां मते पर 100, किश नेईं जां घट्ट पर 0।",
