  "hm.h.recv.how": "कस्टमरें उप्पर {r} बाकी ऐ। तुस रोज लगभग {d} बेचदे ओ, इस करी इक बिल दा पैसा लगभग {n} दिनें च वापस औंदा ऐ।",
  "hm.h.recv.good": "पैसा जल्दी वापस औंदा ऐ। हौली देने आह्‌लें गी याद दुआंदे रौह्‌ओ।",
  "hm.h.recv.ok": "पैसा हौली-हौली वापस औंदा ऐ। बकाया स्क्रीन थमां हर हफ्ते याद दुआओ।",
  "hm.h.recv.low": "पैसा कस्टमरें कोल बड़ी देर तगर फसे दा रौंह्दा ऐ। पैह्लें सारें शा पुराने बिल उगाहो ते नमें आर्डर शा पैह्लें किश पेमेंट मंगो।",
  "hm.h.recv.rule": "कस्टमरें उप्पर बाकी पैसे गी पिछले 3 पूरे म्हीनें दी रोज दी बिक्री कन्नै भाग दित्ता जंदा ऐ। 30 दिन जां घट्ट पर 100, 90 दिन जां मते पर 0।",
  "hm.h.margin": "मार्जिन",
  "hm.h.margin.how": "पिछले 3 म्हीनें च हर 100 दी बिक्री चा खरीद ते खर्चें दे बाद {p} बचेआ। उस शा पैह्लें दे 3 म्हीनें च: {q}।",
  "hm.h.margin.how1": "पिछले 3 म्हीनें च हर 100 दी बिक्री चा खरीद ते खर्चें दे बाद {p} बचेआ।",
  "hm.h.margin.good": "चंगा हिस्सा बचदा ऐ। कीमतां बदलदे बेलै इसगी बचाई रक्खो।",
  "hm.h.margin.ok": "मार्जिन घट्ट ऐ जां घटा करदा ऐ। अपनी बिक्री दियां कीमतां ते मुख्य आइटमें दी लागत दिक्खो।",
  "hm.h.margin.low": "लगभग किश नेईं बचदा। कीमतां बधाओ, खर्चे घटाओ जां घाटे आह्‌ले आइटम बेचना बंद करो।",
  "hm.h.margin.rule": "पिछले 3 पूरे म्हीनें दी बिक्री चा खरीद ते खर्चे घटाइयै, बिक्री दे हिस्से दे तौर पर। 15 जां मते पर 100, 0 जां घट्ट पर 0; जेकर पैह्लें दे 3 म्हीनें शा 5 पॉइंट शा मता डिग्गेआ तां 20 पॉइंट कट्टे जंदे न। हत्थै दा स्टॉक नेईं गिनेआ जंदा।",
  "hm.h.creep": "खर्चें च बाधा",
  "hm.h.creep.how": "पिछले म्हीने तुंदे खर्चे {l} हे; उस शा पैह्लें दे 3 म्हीनें दा औसत {a} हा। एह् {p}% दा बदलाऽ ऐ।",
  "hm.h.creep.good": "खर्चे टिके दे न।",
  "hm.h.creep.ok": "खर्चे बधा करदे न। रिपोर्ट स्क्रीन पर दिक्खो केह्ड़ा हेड बधेआ।",
  "hm.h.creep.low": "खर्चे इक्कदम बधी गे। जेह्ड़ा हेड बधेआ उसगी लब्भो, ते दिक्खो जे ओह् इक बारी दा बिल ते नेईं।",
  "hm.h.creep.rule": "पिछले पूरे म्हीने दे खर्चे उस शा पैह्लें दे 3 म्हीनें दे औसत कन्नै मलाए जंदे न। 5% जां घट्ट बाधे पर 100, 40% जां मते बाधे पर 0। इक बारी दा बड्डा बिल इसगी इक म्हीने आस्तै घटाई देग।",
  "hm.rm.t": "इस डिवाइस पर रिमाइंडर",
  "hm.rm.p": "App खोह्लने पर एह् दसदा ऐ जे अज्ज तुसें केह् करना ऐ। सारें शा जरूरी लाइनें आस्तै तुस फोन नोटिफिकेशन बी दस्सवाई सकदे ओ, हर इक दिनै च इक बारी।",
  "hm.rm.on": "App खोह्लने पर नोटिफिकेशन दस्सो",
  "hm.rm.nosupport": "एह् ब्राउज़र नोटिफिकेशन नेईं दसदा। मेरा दिन दी लिस्ट फ्ही बी चलदी ऐ।",
  "hm.rm.denied": "इस साइट दे नोटिफिकेशन बंद न। ब्राउज़र दी साइट सेटिंग च इनेंगी चालू करो, फ्ही बॉक्स दबारा टिक करो।",
