  "hm.rm.title": "{b}: अज्ज तुंदी लोड़ ऐ",
  "hm.rm.ics": "ड्यू तरीकां फोन दे कैलेंडर च पाओ",
  "hm.rm.icsp": "अगले 60 दिनें दी कैलेंडर फ़ाइल बनांदा ऐ: बिलें दियां ड्यू तरीकां ते टैक्स दियां तरीकां। इनेंगी अपने कैलेंडर च जोड़ने आस्तै फोन पर खोह्लो, जेह्ड़ा इक दिन पैह्लें आपूं बज्जग, App बंद होने पर बी।",
