  "hm.rm.lim": "ब्राउज़र केह् नेईं करी सकदा",
  "hm.rm.l1": "वेब पेज बंद होने पर नेईं चली सकदा, ते इस App दे पिच्छें कोई सर्वर नेईं जेह्ड़ा तुसेंगी पुश मैसेज भेजै। इस करी App दा रिमाइंडर सिर्फ App खोह्लने पर दिक्खदा ऐ।",
  "hm.rm.l2": "सब किश तुंदे डिवाइस पर कड्ढेआ जंदा ऐ, इस करी बिना इंटरनेट बी चलदा ऐ। तुंदे बिजनेस दी कोई गल्ल कुतै नेईं भेजी जंदी।",
  "hm.rm.l3": "जेह्ड़ियां तरीकां छुट्टनियां नेईं चाहिदियां, उंदे आस्तै कैलेंडर फ़ाइल बरतो: तुंदे फोन दा कैलेंडर आपूं बजदा ऐ। एह् अज्जै दी तस्वीर ऐ, इस करी नमें बिल लिखने दे बाद नमीं फ़ाइल बनाओ।",
  "hm.rm.l4": "इंस्टॉल कीते दे App पर, जित्थें फोन इजाजत देऐ, उसदे आइकन पर नंबर दसदा ऐ जे किन्ने जरूरी कम्म न।",
